insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('string-phone','과학','3~4','소리의 성질','종이컵 실전화','말소리가 실을 타고 친구 귀까지 달려가요. 소리가 어떻게 전해지는지 몸으로 느껴 보는 실험이에요.','난이도 ★☆☆ 쉬움','20분',array['구멍 뚫기는 어른과 함께']::text[],array['종이컵']::text[],'assets/img/e1_done.jpg',false,null,$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "종이컵 2개", "how": "다 마신 종이컵을 깨끗이 씻어서", "kit": false}, {"name": "실 3~5m", "how": "연실, 면실, 낚싯줄. 털실은 소리가 잘 안 전해져요.", "kit": false}, {"name": "이쑤시개 1개", "how": "반으로 부러뜨려 2조각. 클립으로 바꿔도 돼요.", "kit": false}, {"name": "연필", "how": "뾰족하게 깎은 연필 (송곳 대신)", "kit": false}, {"name": "가위", "how": "실 자르기용", "kit": false}], "image": "assets/img/e1_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "컵 바닥에 작은 구멍 뚫기", "body": "종이컵 안쪽에서 바닥 한가운데를 연필 끝으로 꾹 눌러 작은 구멍을 내요. 실이 겨우 들어갈 만큼 작게 뚫어야 소리가 잘 전해져요.", "warn": "어른과 함께 해요.", "image": "assets/img/e1_s1.jpg"}, {"title": "실 끼우기", "body": "실 끝을 컵 바깥쪽 구멍으로 넣어서 컵 안쪽으로 빼내요.", "warn": "", "image": null}, {"title": "이쑤시개에 묶기", "body": "컵 안쪽으로 나온 실을 이쑤시개 조각 가운데에 2~3번 단단히 묶어요. 이쑤시개가 구멍을 막아 줘서 실을 당겨도 빠지지 않아요.", "warn": "", "image": "assets/img/e1_s2.jpg"}, {"title": "반대쪽도 똑같이", "body": "실의 다른 끝도 두 번째 컵에 1~3번과 같은 방법으로 연결해요.", "warn": "", "image": null}, {"title": "실을 팽팽하게 당겨 대화하기", "body": "두 사람이 실이 팽팽해질 때까지 멀리 떨어져요. 한 사람은 컵에 입을 대고 작게 말하고, 다른 사람은 컵을 귀에 대고 들어요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["실이 축 늘어졌을 때와 팽팽할 때, 소리가 어떻게 달라지나요?", "친구가 말하는 동안 실을 손가락으로 살짝 만져 보세요. 무엇이 느껴지나요?", "실 가운데를 손으로 꽉 잡으면 어떻게 될까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["말을 하면 컵 바닥이 아주 빠르게 부르르 떨려요. 이 떨림이 팽팽한 실을 타고 친구 컵까지 달려가서, 친구 컵 바닥도 똑같이 떨게 만들어요. 그래서 친구 귀에 내 목소리가 들려요. 실을 손으로 잡으면 떨림이 손에서 멈춰 버려서 소리가 끊겨요."]}, {"label": "부모님께", "paras": ["소리는 물체의 떨림(진동)이 물질을 통해 전달되는 현상입니다. 컵 바닥이 진동판 역할을 하고, 팽팽한 실이 진동을 반대편 컵 바닥까지 전달합니다. 실이 느슨하거나 중간을 잡으면 진동이 흡수되어 전달되지 않습니다.", "이렇게 물어보세요: \"실 말고 다른 걸로 이으면 어떻게 될까?\""]}]}, {"type": "more", "items": [{"title": "실 바꿔 보기", "body": "면실, 낚싯줄, 털실 중 어느 것이 가장 잘 들릴까요?"}, {"title": "길이 바꿔 보기", "body": "2m와 10m 실전화의 소리를 비교해요."}, {"title": "세 명이 통화하기", "body": "실 두 개를 가운데에서 묶으면 셋이 함께 이야기할 수 있어요."}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 소리의 성질 (소리의 발생과 전달)"}]}]$json$::jsonb,1);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('floating-compass','과학','3~4','자석의 성질','병뚜껑 물 위 나침반','바늘 하나와 병뚜껑으로 북쪽을 찾는 나만의 나침반을 만들어요.','난이도 ★☆☆ 쉬움','20분',array['바늘은 어른과 함께']::text[],array['병뚜껑']::text[],'assets/img/e2_done.jpg',false,null,$json$[{"type": "materials", "note": "자석 1개만 있으면 돼요", "rows": [{"name": "바늘 1개", "how": "바느질 바늘. 클립을 곧게 펴서 3cm로 쓰면 더 안전해요.", "kit": false}, {"name": "자석 1개", "how": "막대자석이나 말굽자석. 냉장고 고무 자석은 힘이 약해서 잘 안 될 수 있어요.", "kit": true}, {"name": "병뚜껑 1개", "how": "페트병 플라스틱 뚜껑", "kit": false}, {"name": "넓은 그릇과 물", "how": "국그릇이나 넓은 접시", "kit": false}, {"name": "셀로판테이프", "how": "바늘 고정용", "kit": false}, {"name": "확인용", "how": "스마트폰 나침반 앱", "kit": false}], "image": "assets/img/e2_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "바늘을 자석으로 만들기", "body": "자석의 한쪽 끝으로 바늘을 바늘귀에서 바늘 끝 방향으로 30번 문질러요. 꼭 한 방향으로만 문지르고, 한 번 문지른 뒤에는 자석을 들어 올려 처음 자리로 돌아가요.", "warn": "", "image": "assets/img/e2_s1.jpg"}, {"title": "자석이 됐는지 확인하기", "body": "바늘을 클립에 가까이 대 보세요. 클립이 살짝 끌려오면 성공이에요.", "warn": "", "image": null}, {"title": "병뚜껑에 붙이기", "body": "병뚜껑 안쪽에 바늘을 눕혀 셀로판테이프로 붙여요. 바늘이 뚜껑 한가운데를 지나가게 붙여야 균형이 잘 맞아요.", "warn": "", "image": "assets/img/e2_s2.jpg"}, {"title": "물에 띄우기", "body": "그릇에 물을 담고 병뚜껑을 가운데에 살며시 띄워요. 뚜껑이 천천히 돌다가 한 방향에서 멈춰요. 맨 위 사진처럼요!", "warn": "", "image": null}, {"title": "방향 확인하고 표시하기", "body": "스마트폰 나침반 앱으로 북쪽을 확인해요. 바늘의 어느 끝이 북쪽을 가리키는지 작은 스티커로 표시하면 나만의 나침반 완성!", "warn": "", "image": null}], "notes": ["잘 안 될 때: 실험하는 동안 휴대폰, 스피커, 쇠숟가락은 그릇에서 멀리 두세요. 근처에 쇠붙이나 자석이 있으면 바늘이 그쪽으로 끌려가요."]}, {"type": "questions", "title": "관찰해 봐요", "items": ["뚜껑을 손가락으로 살짝 돌려 놓으면 어떻게 되나요?", "자석을 그릇 옆으로 천천히 가져가면 바늘이 어떻게 움직이나요?", "10번만 문지른 바늘과 30번 문지른 바늘은 무엇이 다른가요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["바늘을 자석으로 문지르면 바늘도 작은 자석이 돼요. 그런데 우리가 사는 지구도 아주아주 큰 자석이에요. 그래서 자석이 된 바늘은 언제나 북쪽과 남쪽을 가리켜요. 물 위에 띄우면 뚜껑이 마음대로 돌 수 있어서 바늘이 스스로 방향을 찾아가요."]}, {"label": "부모님께", "paras": ["쇠로 된 바늘을 자석으로 한 방향으로 문지르면 바늘이 자화되어 약한 자석이 됩니다. 지구는 거대한 자석이므로, 자유롭게 회전하는 자침은 지구 자기장을 따라 남북 방향으로 놓입니다. 물에 띄우면 마찰이 줄어 바늘이 쉽게 돌아갑니다. 어느 끝이 북쪽을 향할지는 문지른 자석의 극에 따라 달라지니 앱으로 확인해 표시하세요. 떨어뜨리거나 시간이 지나 자성이 약해지면 다시 문지르면 됩니다.", "이렇게 물어보세요: \"진짜 나침반 바늘은 왜 한쪽만 빨간색일까?\""]}]}, {"type": "more", "items": [{"title": "동서남북 판 만들기", "body": "이면지에 동서남북을 그려 그릇 아래에 깔아요."}, {"title": "집 안 탐험", "body": "냉장고 옆에서는 바늘이 어떻게 될까요?"}, {"title": "우리 집은 어느 쪽?", "body": "베란다 창문이 어느 방향을 보는지 찾아봐요."}]}, {"type": "note", "text": "안전: 작은 자석, 특히 동그란 강력 자석은 어린 동생이 삼키지 않도록 꼭 높은 곳에 보관해 주세요. 바늘은 실험 후 바늘꽂이에 바로 정리해요."}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "막대자석 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 자석의 성질 (나침반 만들기)"}]}]$json$::jsonb,2);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('shadow-theater','과학','3~4','빛과 그림자','우유팩 그림자 극장','택배 상자가 우리 집 인형극 무대가 돼요. 빛이 어떻게 나아가고 그림자가 왜 생기는지 놀이로 배워요.','난이도 ★★☆ 보통','40분',array['칼은 어른이']::text[],array['우유팩','상자']::text[],'assets/img/e3_done.jpg',false,'assets/pdf/shadow-puppets.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 재활용품으로 만들어요", "rows": [{"name": "무대 틀", "how": "택배 상자 1개", "kit": false}, {"name": "스크린", "how": "얇은 흰 이면지나 종이 포일(베이킹 페이퍼)", "kit": false}, {"name": "인형 판", "how": "우유팩을 펼친 판. 단단해서 오래 써요.", "kit": false}, {"name": "막대", "how": "배달 음식에 딸려 온 나무젓가락", "kit": false}, {"name": "조명", "how": "손전등이나 휴대폰 손전등", "kit": false}, {"name": "도구", "how": "테이프, 가위, 커터칼(어른용)", "kit": false}, {"name": "도안", "how": "그림자 인형 도안 A4 2장 (아래에서 내려받기)", "kit": false}], "image": "assets/img/e3_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "무대 창 만들기", "body": "상자 한 면에 테두리 3cm만 남기고 큰 네모 창을 그린 뒤 오려 내요.", "warn": "커터칼은 어른이 사용해요.", "image": null}, {"title": "스크린 붙이기", "body": "창 안쪽에 흰 이면지를 팽팽하게 붙여요. 주름이 없을수록 그림자가 또렷하게 보여요.", "warn": "", "image": "assets/img/e3_s1.jpg"}, {"title": "인형 만들고 막대 붙이기", "body": "도안을 인쇄해 오린 뒤, 펼친 우유팩에 대고 따라 그려서 한 번 더 오려요. 아래쪽에 나무젓가락을 테이프로 단단히 붙이면 완성이에요. 색칠해도 좋아요. 그림자에는 모양만 나타나요.", "warn": "", "image": "assets/img/e3_s2.jpg"}, {"title": "불 끄고 공연 시작", "body": "방을 어둡게 하고, 상자 뒤 1m쯤에서 손전등으로 스크린을 비춰요. 스크린과 손전등 사이에서 인형을 움직이며 이야기를 들려줘요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "그림자 인형 도안", "desc": "토끼, 거북이, 나무, 집, 해, 달. A4 2장, 실제 크기로 인쇄해 주세요. 점선은 나무젓가락을 붙이는 자리예요.", "pdf": "assets/pdf/shadow-puppets.pdf"}, {"type": "questions", "title": "관찰해 봐요", "items": ["인형을 손전등 가까이 가져가면 그림자 크기가 어떻게 되나요? 스크린 가까이 가져가면요?", "투명한 비닐, 이면지, 우유팩 조각을 비춰 보세요. 그림자가 어떻게 다른가요?", "손전등을 2개 켜면 그림자가 몇 개 생길까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["빛은 언제나 똑바로만 나아가요. 인형이 빛을 가로막으면 그 뒤로는 빛이 가지 못해서 까만 그림자가 생겨요. 인형이 손전등에 가까울수록 빛을 더 넓게 가려서 그림자가 커져요."]}, {"label": "부모님께", "paras": ["빛은 곧게 나아가는 성질(직진)이 있어서, 빛이 통과하지 못하는 불투명한 물체 뒤에는 물체 모양의 그림자가 생깁니다. 광원과 물체가 가까울수록 그림자는 커지고 테두리는 흐려집니다. 이면지 스크린은 빛을 일부만 통과시키는 반투명 물체라서 반대편에서도 그림자가 보입니다.", "이렇게 물어보세요: \"해가 질 때 내 그림자는 왜 길어질까?\""]}]}, {"type": "more", "items": [{"title": "색깔 그림자", "body": "집 창문을 오려 내고 사탕 포장지 같은 색 셀로판을 붙여 보세요."}, {"title": "가족 인형극", "body": "토끼와 거북이 이야기를 우리 가족 버전으로 꾸며요."}, {"title": "손 그림자 놀이", "body": "인형 없이 손만으로 개, 새, 게를 만들어 봐요."}]}, {"type": "info", "items": [{"label": "도면", "value": "그림자 인형 도안 (A4 2장)"}, {"label": "실험 키트", "value": "집 재료로 충분해요 (손전등 없으면 휴대폰)"}, {"label": "교육과정 연결", "value": "3~4학년 빛과 그림자 (빛의 직진, 그림자의 크기)"}]}]$json$::jsonb,3);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('rubber-band-scale','과학','3~4','물체의 무게','고무줄 용수철저울','고무줄이 늘어나는 길이로 물건의 무게를 비교해요. 100원 동전이 우리 집 저울의 추가 돼요.','난이도 ★★☆ 보통','30분','{}'::text[],array['우유팩','종이컵']::text[],'assets/img/e4_s2.jpg',false,'assets/pdf/scale-board.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "우유팩 1개", "how": "펼쳐서 길쭉한 판(약 30cm)으로 써요", "kit": false}, {"name": "고무줄 2~3개", "how": "굵기가 같은 노란 고무줄", "kit": false}, {"name": "클립 3개", "how": "걸이와 고리용", "kit": false}, {"name": "종이컵 1개와 실", "how": "실 3가닥으로 매달아 바구니를 만들어요", "kit": false}, {"name": "100원 동전 10개", "how": "무게를 재는 기준 추 (1개 약 5.4g)", "kit": false}, {"name": "테이프, 가위", "how": "고정하고 오리기용", "kit": false}, {"name": "눈금판 도안", "how": "아래에서 내려받아 인쇄해요", "kit": false}], "image": "assets/img/e4_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "판 만들기", "body": "우유팩을 펼쳐 세로로 긴 판을 만들고, 맨 위에 클립을 꽂아 걸이를 만들어요. 판은 벽이나 문에 테이프로 단단히 붙여요.", "warn": "", "image": null}, {"title": "바구니 매달기", "body": "종이컵 테두리에 구멍 3개를 내고 실을 묶어 바구니를 만들어요. 고무줄을 걸이에 걸고, 고무줄 아래쪽에 클립 고리를 끼워 바구니를 매달아요.", "warn": "", "image": "assets/img/e4_s1.jpg"}, {"title": "눈금판 붙이기", "body": "도안의 눈금판을 오려 판에 붙여요. 빈 바구니일 때 클립 고리가 가리키는 곳이 0이 되도록 맞춰요.", "warn": "", "image": null}, {"title": "동전으로 재기", "body": "동전을 2개씩 넣으면서 고리가 몇 칸 내려가는지 기록표에 적어요. 맨 위 사진처럼요!", "warn": "", "image": null}, {"title": "물건 무게 비교하기", "body": "동전을 빼고 지우개, 연필, 작은 장난감을 넣어 눈금을 읽어요. \"지우개는 동전 몇 개만큼 무거울까?\"", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "저울 눈금판 도안", "desc": "눈금판 2개와 기록표가 들어 있어요. A4 1장, 실제 크기로 인쇄해 주세요.", "pdf": "assets/pdf/scale-board.pdf"}, {"type": "questions", "title": "관찰해 봐요", "items": ["동전이 2개씩 늘어날 때마다 고무줄도 비슷하게 늘어나나요?", "고무줄을 2개 겹쳐 걸면 어떻게 달라지나요?", "바구니를 비우면 고리가 다시 0으로 돌아오나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["물건이 무거울수록 지구가 더 세게 아래로 끌어당겨요. 그래서 고무줄이 더 길게 늘어나요. 늘어난 길이를 보면 어느 쪽이 더 무거운지 알 수 있어요."]}, {"label": "부모님께", "paras": ["무게는 지구가 물체를 당기는 힘의 크기입니다. 용수철은 매단 물체가 무거울수록 일정하게 더 늘어나므로 늘어난 길이로 무게를 잴 수 있습니다. 고무줄도 비슷하게 늘어나지만, 많이 늘어날수록 비례가 조금씩 어긋나서 정확한 측정보다는 무게 비교에 알맞습니다. 그래서 그램 대신 동전 개수를 단위로 쓰는 것을 권합니다.", "이렇게 물어보세요: \"고무줄 대신 진짜 용수철을 쓰면 무엇이 더 좋을까?\""]}]}, {"type": "more", "items": [{"title": "고무줄 바꿔 보기", "body": "굵은 고무줄과 가는 고무줄은 얼마나 다르게 늘어날까요?"}, {"title": "그래프 그리기", "body": "동전 개수와 눈금을 점으로 찍어 이어 봐요."}, {"title": "무게 맞히기 게임", "body": "먼저 손으로 들어 보고 예상한 뒤 저울로 확인해요."}]}, {"type": "info", "items": [{"label": "도면", "value": "저울 눈금판과 기록표 (A4 1장)"}, {"label": "실험 키트", "value": "집 재료로 충분해요 (용수철 세트 준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 물체의 무게 (용수철저울)"}]}]$json$::jsonb,4);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('marker-chromatography','과학','3~4','혼합물의 분리','사인펜 색 분리','검은색 사인펜 속에 숨어 있는 여러 가지 색을 물 한 컵으로 찾아내요.','난이도 ★☆☆ 쉬움','20분',array['아이 혼자서도 할 수 있어요']::text[],'{}'::text[],'assets/img/e5_done.jpg',false,null,$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "커피 필터", "how": "키친타월로 바꿔도 돼요", "kit": false}, {"name": "수성 사인펜", "how": "검정, 갈색, 초록 등 여러 색. 유성 매직은 번지지 않아요.", "kit": false}, {"name": "투명 컵 2~3개", "how": "유리컵이나 투명 플라스틱 컵", "kit": false}, {"name": "연필", "how": "컵 위에 걸치는 막대 (나무젓가락도 OK)", "kit": false}, {"name": "물, 테이프, 가위", "how": "수돗물이면 충분해요", "kit": false}], "image": "assets/img/e5_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "띠 자르기", "body": "커피 필터를 폭 2cm, 길이 10cm 정도의 띠로 잘라요. 색마다 하나씩 여러 개 만들어요.", "warn": "", "image": null}, {"title": "점 찍기", "body": "띠 아래 끝에서 2cm 위에 사인펜으로 콩알만 한 점을 진하게 찍어요. 띠 위쪽에는 연필로 어떤 색인지 적어 둬요.", "warn": "", "image": "assets/img/e5_s1.jpg"}, {"title": "컵에 걸기", "body": "컵에 물을 1cm 정도만 붓고, 띠 위쪽을 연필에 테이프로 붙여 컵 위에 걸쳐요. 띠 끝만 물에 닿고 점은 물보다 위에 있어야 해요.", "warn": "", "image": "assets/img/e5_s2.jpg"}, {"title": "기다리며 지켜보기", "body": "10~15분 동안 물이 띠를 타고 올라가는 모습을 지켜봐요. 물이 위쪽 끝 가까이 오면 꺼내서 말려요.", "warn": "", "image": null}, {"title": "나란히 비교하기", "body": "마른 띠를 나란히 놓고 각 색에 어떤 색들이 숨어 있었는지 비교해요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["검은색 점은 어떤 색들로 나뉘었나요?", "가장 높이 올라간 색과 가장 낮게 남은 색은 무엇인가요?", "회사가 다른 검은 사인펜끼리도 결과가 같을까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["검은색 사인펜 잉크는 사실 여러 가지 색을 섞어서 만든 거예요. 물이 종이를 타고 올라갈 때 색깔들도 함께 따라 올라가는데, 빨리 달리는 색과 천천히 걷는 색이 있어서 서로 떨어지게 돼요."]}, {"label": "부모님께", "paras": ["사인펜 잉크는 여러 색소가 섞인 혼합물입니다. 물이 종이를 따라 올라가는 동안, 물에 잘 녹고 종이에 덜 달라붙는 색소는 멀리 이동하고 그렇지 않은 색소는 덜 이동해 서로 분리됩니다. 이 방법을 크로마토그래피라고 하며, 섞인 물질을 성질의 차이로 나눌 수 있다는 것을 보여 줍니다.", "이렇게 물어보세요: \"섞여 있는 것을 다시 나누는 방법에는 또 무엇이 있을까?\""]}]}, {"type": "more", "items": [{"title": "꽃무늬 만들기", "body": "동그란 필터 가운데에 점을 찍고 물을 한 방울씩 떨어뜨려요."}, {"title": "사인펜 탐정", "body": "가족이 몰래 쓴 사인펜을 색 띠로 찾아내요."}, {"title": "책갈피 만들기", "body": "마른 띠를 두꺼운 종이에 붙이면 나만의 책갈피가 돼요."}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 혼합물의 분리"}]}]$json$::jsonb,5);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('bottle-lung','과학','5~6','우리 몸의 구조와 기능','페트병 폐 모형','페트병 속 풍선이 숨을 쉬어요. 우리가 어떻게 공기를 들이마시는지 눈으로 확인해요.','난이도 ★★☆ 보통','30분',array['페트병 자르기는 어른이']::text[],array['페트병']::text[],'assets/img/e6_done.jpg',false,null,$json$[{"type": "materials", "note": "풍선 2개만 있으면 돼요", "rows": [{"name": "작은 페트병 1개", "how": "300~500mL 투명 생수병", "kit": false}, {"name": "풍선 2개", "how": "작은 것 1개, 보통 것 1개", "kit": true}, {"name": "빨대 1개", "how": "굵은 빨대가 좋아요", "kit": false}, {"name": "찰흙이나 클레이", "how": "병 입구 빈틈을 막는 용도", "kit": false}, {"name": "고무줄 2개, 테이프, 가위", "how": "고정하고 자르기용", "kit": false}], "image": "assets/img/e6_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "병 바닥 잘라 내기", "body": "페트병 바닥에서 3cm 위를 잘라 내요. 잘린 면이 날카로우면 테이프를 한 바퀴 둘러요.", "warn": "자르기는 어른이 해요.", "image": null}, {"title": "빨대에 풍선 달기 (허파)", "body": "작은 풍선 입구에 빨대를 넣고 고무줄로 단단히 감아 공기가 새지 않게 해요. 이 풍선이 '허파'예요.", "warn": "", "image": "assets/img/e6_s1.jpg"}, {"title": "병 입구 막기", "body": "풍선이 병 안쪽으로 들어가도록 빨대를 병 입구에 꽂고, 빈틈을 찰흙으로 꼼꼼히 막아요. 틈이 있으면 실험이 잘 안 돼요.", "warn": "", "image": null}, {"title": "가로막 만들기", "body": "보통 풍선의 입구를 묶고 둥근 아랫부분을 잘라 내요. 남은 부분을 병의 잘린 바닥에 팽팽하게 씌우고 고무줄로 고정해요. 이것이 '가로막'이에요.", "warn": "", "image": null}, {"title": "숨쉬기", "body": "아래 풍선의 매듭을 잡고 살짝 당겨 보세요. 병 안의 풍선이 부풀어요. 손을 놓으면 다시 오그라들어요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["아래 막을 당길 때와 밀어 올릴 때 안쪽 풍선은 어떻게 되나요?", "입구의 찰흙에 틈을 내면 어떻게 될까요?", "내 배에 손을 얹고 크게 숨을 쉬어 보세요. 무엇이 움직이나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["가슴 아래에는 '가로막'이라는 얇은 근육이 있어요. 가로막이 아래로 내려가면 가슴 속 공간이 넓어지고, 그 틈으로 바깥 공기가 허파 안으로 쑥 들어와요. 페트병의 아래 풍선이 가로막, 안쪽 풍선이 허파 역할을 해요."]}, {"label": "부모님께", "paras": ["숨을 들이쉴 때는 가로막이 내려가고 갈비뼈가 올라가 가슴 속 공간이 커집니다. 공간이 커지면 안쪽 압력이 낮아져 바깥 공기가 기관을 따라 폐로 들어옵니다. 이 모형은 가로막의 움직임만 보여 주므로, 실제로는 갈비뼈 사이 근육도 함께 움직인다는 점을 덧붙여 주세요.", "이렇게 물어보세요: \"빨대는 우리 몸의 어디에 해당할까?\""]}]}, {"type": "more", "items": [{"title": "허파 두 개 만들기", "body": "빨대 두 개를 Y자로 이어 풍선 2개를 달아요."}, {"title": "숨 세기", "body": "1분 동안 숨을 몇 번 쉬는지 세고, 제자리 뛰기 후와 비교해요."}, {"title": "풍선 크기 바꾸기", "body": "안쪽 풍선이 크면 어떻게 달라질까요?"}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "풍선 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 우리 몸의 구조와 기능 (호흡 기관)"}]}]$json$::jsonb,6);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('cabbage-indicator','과학','5~6','산과 염기','적양배추 산·염기 지시약','보라색 양배추 물이 식초를 만나면 분홍색, 베이킹소다를 만나면 파란색으로 변해요.','난이도 ★★☆ 보통','40분',array['뜨거운 물은 어른이']::text[],'{}'::text[],'assets/img/e7_done.jpg',false,'assets/pdf/ph-color-chart.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 부엌에 있는 재료", "rows": [{"name": "적양배추 잎 2~3장", "how": "잘게 찢어서 써요", "kit": false}, {"name": "뜨거운 물", "how": "전기포트 물 (어른이 부어요)", "kit": false}, {"name": "투명 컵 6개", "how": "유리컵이나 투명 플라스틱 컵", "kit": false}, {"name": "체", "how": "주방용 체나 거름망", "kit": false}, {"name": "산성 재료", "how": "식초, 레몬즙", "kit": false}, {"name": "염기성 재료", "how": "베이킹소다, 비눗물", "kit": false}, {"name": "색 비교표 도안", "how": "아래에서 내려받아 인쇄해요", "kit": false}], "image": "assets/img/e7_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "양배추 물 우리기", "body": "잘게 찢은 잎을 그릇에 담고 뜨거운 물을 부어 10분 기다려요. 진한 보라색 물이 나오면 체로 걸러요.", "warn": "뜨거운 물은 어른이 다뤄요.", "image": "assets/img/e7_s1.jpg"}, {"title": "컵에 나눠 담기", "body": "식은 양배추 물을 투명 컵 여러 개에 3cm씩 나눠 담아요. 한 컵은 비교용으로 그대로 둬요.", "warn": "", "image": null}, {"title": "산성 재료 넣기", "body": "식초와 레몬즙을 한 숟가락씩 서로 다른 컵에 넣어요. 색이 어떻게 변하나요?", "warn": "", "image": "assets/img/e7_s2.jpg"}, {"title": "염기성 재료 넣기", "body": "베이킹소다를 물에 녹여 다른 컵에 넣고, 비눗물도 넣어 봐요.", "warn": "", "image": null}, {"title": "색 비교표와 맞춰 보기", "body": "색 비교표 옆에 컵을 줄 세우고, 산성인지 염기성인지 기록표에 적어요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": ["안전: 락스, 변기 세정제 같은 청소용 세제는 절대 섞지 마세요. 위험한 기체가 나올 수 있어요. 실험한 물은 마시지 말고 싱크대에 버려요."]}, {"type": "template", "title": "산·염기 색 비교표", "desc": "색 안내표와 내 실험 기록표가 들어 있어요. A4 1장, 컬러로 인쇄하면 좋아요.", "pdf": "assets/pdf/ph-color-chart.pdf"}, {"type": "questions", "title": "관찰해 봐요", "items": ["가장 진한 분홍색이 된 컵은 무엇을 넣은 컵인가요?", "식초 컵에 베이킹소다를 조금씩 넣으면 어떤 일이 생기나요?", "우유, 사이다, 치약 녹인 물은 어느 쪽일까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["적양배추 속에는 '색깔 탐정' 물질이 들어 있어요. 이 탐정은 신맛 나는 산성을 만나면 분홍색 옷으로, 미끈미끈한 염기성을 만나면 파란색이나 초록색 옷으로 갈아입어요. 그래서 색만 보고도 산성인지 염기성인지 알 수 있어요."]}, {"label": "부모님께", "paras": ["적양배추에는 안토시아닌이라는 색소가 있어, 용액의 산성과 염기성 정도(pH)에 따라 색이 달라집니다. 이렇게 색으로 산성과 염기성을 알려 주는 물질을 지시약이라고 합니다. 식초에 베이킹소다를 넣으면 거품이 나며 색이 보라색 쪽으로 돌아가는데, 산과 염기가 서로의 성질을 약하게 만드는 중화 반응입니다.", "이렇게 물어보세요: \"양배추 물로 리트머스 종이 같은 지시약 종이를 만들 수 있을까?\""]}]}, {"type": "more", "items": [{"title": "양배추 종이 만들기", "body": "키친타월을 양배추 물에 적셔 말린 뒤 잘라서 써요."}, {"title": "색 되돌리기", "body": "분홍 컵에 베이킹소다 물을 한 방울씩 넣어 보라색으로 되돌려요."}, {"title": "비밀 편지", "body": "식초로 글씨를 쓰고 말린 뒤 양배추 물을 바르면 글씨가 나타나요."}]}, {"type": "info", "items": [{"label": "도면", "value": "산·염기 색 비교표 (A4 1장)"}, {"label": "실험 키트", "value": "부엌 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 산과 염기 (지시약, 중화)"}]}]$json$::jsonb,7);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('water-lens','과학','5~6','빛과 렌즈','페트병 물 돋보기','물이 담긴 페트병과 물방울 하나로 작은 글씨를 크게 보는 돋보기를 만들어요.','난이도 ★☆☆ 쉬움','15분',array['햇빛 드는 곳에 두지 않기']::text[],array['페트병']::text[],'assets/img/e8_done.jpg',false,null,$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "투명 페트병 1개", "how": "무늬 없이 매끈한 둥근 병. 라벨은 떼요.", "kit": false}, {"name": "물", "how": "수돗물", "kit": false}, {"name": "비닐 랩", "how": "주방용 랩", "kit": false}, {"name": "숟가락", "how": "물방울을 떨어뜨리는 용도 (스포이트도 OK)", "kit": false}, {"name": "신문이나 책", "how": "글씨가 작은 것", "kit": false}], "image": "assets/img/e8_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "물병 돋보기 만들기", "body": "페트병에 물을 가득 채우고 뚜껑을 꼭 닫아요. 공기 방울이 적을수록 또렷하게 보여요.", "warn": "", "image": null}, {"title": "글씨 위에서 보기", "body": "병을 눕혀 신문 위에 올리고 글씨를 봐요. 병을 조금씩 들어 올리며 글씨가 어떻게 바뀌는지 살펴봐요. 위아래로는 그대로인데 옆으로만 넓어지는 것도 찾아봐요.", "warn": "", "image": null}, {"title": "물방울 돋보기 만들기", "body": "신문 위에 랩을 펴고, 숟가락으로 물을 한 방울 떨어뜨려요. 물방울 아래 글씨를 들여다봐요.", "warn": "", "image": "assets/img/e8_s2.jpg"}, {"title": "물방울 크기 바꾸기", "body": "작은 물방울과 큰 물방울 중 어느 쪽이 글씨를 더 크게 보여 주는지 비교해요.", "warn": "", "image": null}, {"title": "주변 관찰하기", "body": "물병 돋보기로 나뭇잎 잎맥, 손가락 지문, 그림책을 살펴봐요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": ["안전: 둥근 물병은 햇빛을 한 점으로 모아 불이 날 수 있어요. 물이 든 페트병을 햇빛 드는 창가나 자동차 안에 두지 마세요."]}, {"type": "questions", "title": "관찰해 봐요", "items": ["물병 돋보기는 왜 옆으로만 커 보일까요?", "물방울 돋보기는 왜 모든 방향으로 커 보일까요?", "물을 비운 빈 병으로 보면 어떻게 될까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["물이 둥글게 볼록한 모양이 되면 빛이 그 안을 지나면서 살짝 꺾여요. 꺾인 빛이 우리 눈에 들어오면 물건이 실제보다 크게 보여요. 진짜 돋보기도 가운데가 볼록한 유리로 만들어요."]}, {"label": "부모님께", "paras": ["가운데가 두껍고 가장자리가 얇은 볼록렌즈는 빛을 굴절시켜 가까운 물체를 크게 보이게 합니다. 물방울은 사방으로 둥근 볼록렌즈라 모든 방향으로 커 보이고, 눕힌 원통형 물병은 한 방향으로만 휘어 있어 그 방향으로만 늘어나 보입니다. 볼록렌즈가 햇빛을 모으는 성질 때문에 생기는 화재 위험도 함께 이야기해 주세요.", "이렇게 물어보세요: \"할머니 돋보기 안경은 어떤 모양의 렌즈일까?\""]}]}, {"type": "more", "items": [{"title": "식용유 돋보기", "body": "물 대신 식용유 방울로 보면 더 크게 보일까요?"}, {"title": "유리컵 비교", "body": "물을 채운 둥근 컵과 네모난 통으로 보면 무엇이 다를까요?"}, {"title": "관찰 일기", "body": "돋보기로 본 것을 크게 그려서 기록해요."}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "집 재료로 충분해요 (볼록렌즈 세트 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 빛과 렌즈 (볼록렌즈)"}]}]$json$::jsonb,8);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('star-projector','과학','5~6','태양계와 별','휴지심 별자리 투영기','휴지심과 손전등으로 우리 방 천장에 북두칠성을 띄워요. 밤하늘에서 북극성을 찾는 법도 함께 배워요.','난이도 ★★☆ 보통','30분',array['압정 사용 주의']::text[],array['휴지심']::text[],'assets/img/e9_done.jpg',false,'assets/pdf/star-templates.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 휴대폰 손전등도 OK", "rows": [{"name": "휴지심 3개", "how": "다 쓴 두루마리 휴지 심", "kit": false}, {"name": "검은 종이", "how": "검은 도화지. 없으면 이면지를 매직으로 검게 칠해요.", "kit": false}, {"name": "고무줄 3개", "how": "종이를 고정하는 용도", "kit": false}, {"name": "압정 1개", "how": "굵은 바늘도 돼요. 아래에 접은 수건을 깔아요.", "kit": false}, {"name": "손전등", "how": "휴대폰 손전등도 돼요", "kit": false}, {"name": "별자리 도안", "how": "아래에서 내려받아 인쇄해요", "kit": false}], "image": "assets/img/e9_mat.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "도안 오리기", "body": "도안을 인쇄해 별자리 동그라미를 바깥 점선을 따라 오려요.", "warn": "", "image": null}, {"title": "별 구멍 뚫기", "body": "검은 종이 위에 도안을 겹쳐 대고, 접은 수건 위에서 흰 점마다 압정으로 구멍을 뚫어요. 밝은 별은 압정을 살짝 돌려 조금 더 크게 뚫어요.", "warn": "", "image": "assets/img/e9_s1.jpg"}, {"title": "휴지심에 씌우기", "body": "구멍 뚫린 검은 종이를 휴지심 한쪽 끝에 씌우고 고무줄로 팽팽하게 고정해요. 휴지심 옆면에 별자리 이름을 적어 둬요.", "warn": "", "image": null}, {"title": "천장에 띄우기", "body": "방을 어둡게 하고, 휴지심 반대쪽 끝에 손전등을 대고 천장을 비춰요. 휴지심을 천장에 가까이, 멀리 해 보며 별이 또렷해지는 거리를 찾아요. 맨 위 사진처럼요!", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "별자리 도안 3종", "desc": "북두칠성, 카시오페이아, 오리온. 천장에 비쳤을 때 바른 모양이 되도록 도안은 좌우를 뒤집어 그렸어요. A4 1장.", "pdf": "assets/pdf/star-templates.pdf"}, {"type": "questions", "title": "관찰해 봐요", "items": ["휴지심을 천장에서 멀리 하면 별자리 크기는 어떻게 되나요?", "북두칠성 국자 끝의 두 별을 이은 길이를 다섯 배 늘리면 어디에 닿을까요?", "카시오페이아와 북두칠성은 어느 별을 사이에 두고 마주 보고 있을까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["손전등 빛은 검은 종이에 막히고, 작은 구멍으로만 빠져나가요. 빛은 똑바로 나아가니까 구멍 모양 그대로 천장에 점이 찍혀요. 진짜 별들도 아주아주 멀리 있어서 밤하늘에 작은 점처럼 보여요."]}, {"label": "부모님께", "paras": ["빛이 곧게 나아가는 성질 때문에 구멍 배열이 그대로 확대되어 천장에 비칩니다. 별자리는 지구에서 볼 때 비슷한 방향에 보이는 별들을 이어 이름 붙인 것으로, 실제로는 별마다 지구와의 거리가 크게 다릅니다. 북두칠성 국자 끝 두 별 사이 거리를 약 다섯 배 늘이면 북극성을 찾을 수 있으니, 맑은 날 북쪽 하늘에서 함께 찾아보세요.", "이렇게 물어보세요: \"별자리는 계절마다 왜 다르게 보일까?\""]}]}, {"type": "more", "items": [{"title": "우리 가족 별자리", "body": "가족 이름의 첫 글자나 반려동물 모양으로 나만의 별자리를 만들어요."}, {"title": "진짜 하늘 찾기", "body": "맑은 밤 북쪽 하늘에서 북두칠성과 북극성을 찾아봐요."}, {"title": "별자리 이야기", "body": "별자리에 얽힌 옛이야기를 찾아 천장 극장으로 들려줘요."}]}, {"type": "info", "items": [{"label": "도면", "value": "별자리 도안 3종 (A4 1장)"}, {"label": "실험 키트", "value": "집 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 태양계와 별 (별자리, 북극성 찾기)"}]}]$json$::jsonb,9);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('milk-carton-torch','과학','5~6','전기의 이용','우유팩 손전등','우유팩과 LED로 진짜 켜지는 손전등을 만들며 전기 회로를 배워요.','난이도 ★★★ 도전','50분',array['건전지 취급 주의']::text[],array['우유팩']::text[],'assets/img/e10_done.jpg',false,'assets/pdf/torch-circuit.pdf',$json$[{"type": "materials", "note": "전기 부품 4가지가 필요해요 · DNA 키즈랩 키트 1호 후보", "rows": [{"name": "LED 1개", "how": "3V용, 지름 5mm 흰색 LED", "kit": true}, {"name": "건전지 끼우개", "how": "AA 2개용, 빨간 선·검은 선 달린 것", "kit": true}, {"name": "할핀 2개, 클립 1개", "how": "스위치용. 클립은 집에 있는 것", "kit": true}, {"name": "AA 건전지 2개", "how": "리모컨용 건전지", "kit": false}, {"name": "우유팩 1개", "how": "손전등 몸통", "kit": false}, {"name": "알루미늄 호일", "how": "반사판에 붙여 빛을 모아요", "kit": false}, {"name": "테이프, 가위, 송곳", "how": "송곳은 어른이 사용해요", "kit": false}], "image": "assets/img/t_torch.jpg"}, {"type": "steps", "title": "만드는 방법", "items": [{"title": "몸통 만들기", "body": "우유팩 윗부분을 잘라 내고, 건전지 끼우개가 안에 쏙 들어가는지 확인해요.", "warn": "", "image": null}, {"title": "클립 스위치 만들기", "body": "우유팩 옆면에 3cm 간격으로 할핀 두 개를 꽂고, 한쪽 할핀에 클립을 걸어요. 클립을 돌려 다른 할핀에 닿게 하면 불이 켜지는 스위치가 돼요.", "warn": "할핀 구멍은 어른이 송곳으로 뚫어요.", "image": "assets/img/e10_s2.jpg"}, {"title": "반사판 만들기", "body": "도안의 반사판을 오려 안쪽에 호일을 붙이고 원뿔 모양으로 말아요. 가운데 작은 구멍에 LED를 끼워요.", "warn": "", "image": null}, {"title": "회로 연결하기", "body": "회로 연결도를 보며 연결해요. LED의 긴 다리(+)는 빨간 선에, 짧은 다리(−)는 할핀 하나에, 다른 할핀은 검은 선에 감아 테이프로 고정해요.", "warn": "", "image": null}, {"title": "불 켜기", "body": "건전지를 넣고 반사판을 우유팩 입구에 테이프로 붙여요. 클립 스위치를 닫으면 불이 켜져요. 맨 위 사진처럼요! 안 켜지면 LED 다리 방향을 바꿔 다시 연결해 보세요.", "warn": "", "image": null}], "notes": ["안전 LED는 3V용을 쓰고, 건전지는 2개까지만 연결해요. 더 많이 연결하면 LED가 타 버려요. 빨간 선과 검은 선이 직접 닿으면(합선) 건전지가 뜨거워져요. 다 쓰면 건전지를 빼 두세요. 동전 모양 리튬 건전지는 아이가 삼키면 매우 위험해요. 이 실험에는 쓰지 말고 손 닿지 않는 곳에 보관해요."]}, {"type": "template", "title": "회로 연결도와 반사판 전개도", "desc": "회로를 어떻게 이어야 하는지 그림으로 보여 주고, 반사판을 오려 만들 수 있는 전개도가 들어 있어요. A4 1장 (위 준비물 옆 미리보기).", "pdf": "assets/pdf/torch-circuit.pdf"}, {"type": "questions", "title": "관찰해 봐요", "items": ["클립 스위치를 열면 불이 어떻게 되나요? 왜 그럴까요?", "LED 다리를 거꾸로 연결하면 어떻게 되나요?", "반사판이 있을 때와 없을 때 벽에 비친 빛은 어떻게 다른가요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["전기는 건전지에서 나와 전선을 따라 한 바퀴 빙 돌아 다시 건전지로 돌아가야만 흘러요. 이 길이 이어지면 LED에 불이 켜지고, 클립 스위치를 열어 길을 끊으면 불이 꺼져요. LED는 한쪽 방향으로만 전기를 통과시켜서 다리 방향이 중요해요."]}, {"label": "부모님께", "paras": ["전지, 전선, 스위치, 전구(LED)가 끊김 없이 이어진 닫힌 회로에서만 전류가 흐릅니다. 스위치는 회로를 열고 닫는 장치입니다. LED는 전류가 한 방향으로만 흐르는 소자라 +와 − 방향이 맞아야 켜지는데, 교과서의 꼬마전구와 다른 점이니 비교해 이야기해 주세요. 호일 반사판은 옆으로 퍼지는 빛을 앞으로 모아 줍니다.", "이렇게 물어보세요: \"우리 집 전등 스위치는 회로의 어디를 끊고 이을까?\""]}]}, {"type": "more", "items": [{"title": "전기가 통하는 물건 찾기", "body": "클립 대신 지우개, 동전, 나무젓가락을 대 보며 불이 켜지는지 확인해요."}, {"title": "색깔 손전등", "body": "반사판 입구에 색 셀로판을 씌워 봐요."}, {"title": "모스 부호 놀이", "body": "스위치를 짧게, 길게 눌러 가족에게 신호를 보내요."}]}, {"type": "info", "items": [{"label": "도면", "value": "회로 연결도와 반사판 전개도 (A4 1장)"}, {"label": "실험 키트", "value": "LED·건전지 끼우개·할핀 세트 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 전기의 이용 (전기 회로, 스위치)"}]}]$json$::jsonb,10);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('pizza-fractions','수학','3~4','분수','피자 상자 분수판','피자 상자를 잘라 만든 분수판으로 1/2과 1/4 중 어느 쪽이 더 큰지 손으로 확인해요.','난이도 ★☆☆ 쉬움','40분',array['칼은 어른이']::text[],array['상자']::text[],'assets/img/m1.jpg',false,'assets/pdf/fraction-circles.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "두꺼운 종이 상자", "how": "피자 상자나 택배 상자를 펼쳐서", "kit": false}, {"name": "분수 원판 도안", "how": "아래에서 내려받아 컬러로 인쇄해요", "kit": false}, {"name": "풀, 가위, 커터칼", "how": "상자 자르기는 어른이 해요", "kit": false}, {"name": "네임펜", "how": "조각 뒷면에 분수를 적어요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "도안 붙이기", "body": "도안을 인쇄해 원 6개를 오리고, 펼친 상자 판에 풀로 붙여요.", "warn": "", "image": null}, {"title": "조각 자르기", "body": "원 테두리와 안쪽 선을 따라 조각을 잘라요. 조각 뒷면에 1/2, 1/3처럼 분수를 적어 둬요.", "warn": "두꺼운 상자는 어른이 커터칼로 잘라 주세요.", "image": null}, {"title": "전체 위에 덮어 보기", "body": "노란 '1' 원 위에 1/2 조각 두 개를 올려 보세요. 딱 맞게 덮이나요? 1/4 조각 몇 개로 덮을 수 있는지도 세어 봐요.", "warn": "", "image": null}, {"title": "크기 비교 게임", "body": "조각 두 개를 골라 겹쳐 보고 더 큰 쪽을 맞혀요. \"1/3 피자와 1/4 피자 중 어느 쪽을 먹을래?\"", "warn": "", "image": null}, {"title": "같은 크기 찾기", "body": "1/2 조각 하나를 다른 조각들로 똑같이 덮어 보세요. 1/4로는 몇 개, 1/8로는 몇 개가 필요한가요?", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "분수 원판 도안", "desc": "전체, 1/2, 1/3, 1/4, 1/6, 1/8 원판 6장. 분모마다 색이 달라 아이가 쉽게 구분해요. A4 1장.", "pdf": "assets/pdf/fraction-circles.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["아래 숫자가 커질수록 한 조각의 크기는 어떻게 되나요?", "1/4 조각 3개를 모으면 원의 얼마만큼이 될까요?", "크기가 다르게 자른 조각도 1/4이라고 부를 수 있을까요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["피자를 똑같이 나눌수록 한 조각은 작아져요. 2명이 나누면 1/2, 4명이 나누면 1/4이에요. 아래 숫자는 몇 조각으로 똑같이 나눴는지, 위 숫자는 그중 몇 조각을 가졌는지를 알려 줘요."]}, {"label": "부모님께", "paras": ["분수는 '전체를 똑같이 나눈 것 가운데 몇'입니다. 3~4학년에서는 분수의 뜻, 단위분수(분자가 1인 분수)의 크기 비교, 크기가 같은 분수를 다룹니다. 조각을 직접 겹쳐 보면 '숫자가 크면 더 크다'는 흔한 착각, 즉 1/4이 1/2보다 크다는 생각을 자연스럽게 바로잡을 수 있습니다. '똑같이' 나누는 것이 핵심이라는 점도 꼭 짚어 주세요.", "이렇게 물어보세요: \"피자를 친구 몇 명이랑 나눠 먹으면 더 큰 조각을 먹을 수 있을까?\""]}]}, {"type": "more", "items": [{"title": "식탁에서 분수 말하기", "body": "케이크나 사과를 나눌 때 \"이건 몇 분의 몇?\" 하고 물어요."}, {"title": "같은 크기 사슬", "body": "1/2 = 2/4 = 4/8을 조각으로 줄 세워요."}, {"title": "분수 피자 가게", "body": "\"3/8 피자 주세요\" 주문을 받아 조각을 골라 줘요."}]}, {"type": "info", "items": [{"label": "도안", "value": "분수 원판 6장 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 분수 (단위분수, 크기 비교)"}]}]$json$::jsonb,11);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('egg-tray-arrays','수학','3~4','곱셈','달걀판 곱셈 배열','달걀판 칸에 병뚜껑을 줄 맞춰 놓으면 곱셈이 눈에 보여요. 주사위 두 개로 하는 곱셈 놀이예요.','난이도 ★☆☆ 쉬움','20분','{}'::text[],array['병뚜껑']::text[],'assets/img/m2.jpg',false,'assets/pdf/array-record.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 병뚜껑을 모아 두세요", "rows": [{"name": "종이 달걀판 2개", "how": "30구 달걀판 2개를 나란히 붙이면 6×6까지 놓을 수 있어요", "kit": false}, {"name": "병뚜껑 36개", "how": "페트병 뚜껑. 단추나 콩으로 바꿔도 돼요.", "kit": false}, {"name": "주사위 2개", "how": "보드게임 주사위. 없으면 1~6 숫자 카드를 만들어요.", "kit": false}, {"name": "곱셈 기록판 도안", "how": "아래에서 내려받아 인쇄해요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "주사위 굴리기", "body": "주사위 두 개를 굴려 나온 수를 기록판에 적어요. 예를 들어 3과 4가 나왔어요.", "warn": "", "image": null}, {"title": "배열 만들기", "body": "첫째 수만큼 줄을 만들고, 한 줄에 둘째 수만큼 병뚜껑을 놓아요. 3줄에 4개씩 놓으면 돼요.", "warn": "", "image": null}, {"title": "뛰어 세기", "body": "하나씩 세지 말고 한 줄씩 \"4, 8, 12\" 하고 뛰어 세요. 이것이 곱셈식 3 × 4 = 12예요.", "warn": "", "image": null}, {"title": "달걀판 돌려 보기", "body": "달걀판을 옆으로 돌리면 4줄에 3개씩이 돼요. 4 × 3도 12인지 세어 봐요.", "warn": "", "image": null}, {"title": "기록판에 색칠하기", "body": "기록판 칸에 배열만큼 색칠하고, 곱셈식과 덧셈식(4 + 4 + 4 = 12)을 함께 써요. 여섯 번 반복해요.", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "곱셈 배열 기록판", "desc": "주사위 수, 6×6 색칠 칸, 곱셈식과 덧셈식을 적는 칸이 여섯 번 들어 있어요. A4 1장.", "pdf": "assets/pdf/array-record.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["3 × 4와 4 × 3은 왜 답이 같을까요?", "병뚜껑 12개로 만들 수 있는 직사각형 배열은 몇 가지일까요?", "병뚜껑 7개로는 직사각형을 몇 가지 만들 수 있나요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["곱셈은 같은 수를 여러 번 더하는 것을 빠르게 하는 방법이에요. 3줄에 4개씩이면 4 + 4 + 4이고, 줄여서 3 × 4라고 써요. 달걀판을 돌려도 병뚜껑 수는 그대로라서 4 × 3도 12예요."]}, {"label": "부모님께", "paras": ["가로세로로 줄 맞춘 배열은 곱셈을 '같은 묶음의 반복'으로 이해하게 하는 좋은 모델이며, 이후 두 자리 수 곱셈과 5학년 넓이 개념으로 이어집니다. 달걀판을 돌려 보는 활동은 곱하는 순서를 바꿔도 결과가 같다는 성질을 눈으로 보여 줍니다. 구구단을 외우기 전에 '왜 그런지'를 손으로 경험하게 하는 것이 목표입니다.", "이렇게 물어보세요: \"하나씩 세는 것보다 빨리 세는 방법이 있을까?\""]}]}, {"type": "more", "items": [{"title": "24 만들기", "body": "병뚜껑 24개로 만들 수 있는 배열을 모두 찾아요."}, {"title": "곱셈 빙고", "body": "주사위 곱을 빙고판에서 지워 가며 한 줄을 먼저 완성해요."}, {"title": "생활 속 배열 찾기", "body": "초콜릿, 아파트 창문, 달력에서 곱셈 배열을 찾아요."}]}, {"type": "info", "items": [{"label": "도안", "value": "곱셈 배열 기록판 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 곱셈 (곱셈의 뜻, 곱하는 순서)"}]}]$json$::jsonb,12);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('recycling-bar-graph','수학','3~4','자료의 정리','재활용품 막대그래프','일주일 동안 우리 집 재활용품을 세어 막대그래프로 그려요. 수학과 환경 공부를 한 번에 해요.','난이도 ★☆☆ 쉬움','일주일 (하루 2분)','{}'::text[],'{}'::text[],'assets/img/m3.jpg',false,'assets/pdf/recycling-survey.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 분리수거함과 기록지만 있으면 돼요", "rows": [{"name": "조사 기록지 도안", "how": "아래에서 내려받아 인쇄해요 (표와 그래프가 한 장에)", "kit": false}, {"name": "연필, 색연필", "how": "막대마다 다른 색으로 칠하면 보기 좋아요", "kit": false}, {"name": "자석이나 테이프", "how": "기록지를 분리수거함 옆에 붙여 둬요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "기록지 붙이기", "body": "월요일 아침, 분리수거함 옆에 기록지를 붙여요.", "warn": "", "image": null}, {"title": "버릴 때마다 표시하기", "body": "가족 누구든 재활용품을 버릴 때 해당 칸에 바를 정(正) 한 획을 그어요. 아이가 '기록 담당'이 되면 더 재미있어요.", "warn": "", "image": null}, {"title": "합계 세기", "body": "일요일에 종류별로 모두 몇 개인지 세어요. 바를 정 한 글자가 5개라는 것을 이용하면 빨리 셀 수 있어요.", "warn": "", "image": null}, {"title": "막대그래프 그리기", "body": "가로에는 종류, 세로에는 개수를 나타내요. 합계만큼 칸을 색칠해 막대를 만들어요.", "warn": "", "image": null}, {"title": "가족 회의하기", "body": "가장 많이 나온 것과 가장 적게 나온 것을 찾고, 다음 주에 줄일 방법을 정해요.", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "재활용품 조사 기록지", "desc": "요일별 표시 표와 막대그래프 칸이 한 장에 들어 있어요. 매주 새로 인쇄해 비교해 보세요. A4 1장.", "pdf": "assets/pdf/recycling-survey.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["표와 막대그래프 중 어느 쪽이 가장 많은 것을 찾기 쉬운가요?", "세로 눈금 한 칸을 2개로 정하면 그래프가 어떻게 달라질까요?", "다음 주에는 어떤 막대가 짧아졌으면 좋겠나요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["조사한 수를 막대 길이로 그리면 어느 것이 많고 적은지 한눈에 보여요. 막대가 길수록 많은 거예요. 숫자를 하나하나 비교하지 않아도 그림만 보고 알 수 있어요."]}, {"label": "부모님께", "paras": ["자료를 모으고, 분류하고, 표로 정리하고, 그래프로 나타내고, 해석하는 과정 전체를 경험하는 활동입니다. 3학년 그림그래프, 4학년 막대그래프와 연결되며, 세로 눈금 한 칸의 크기를 정하는 것이 막대그래프의 핵심입니다. 결과를 보고 \"어떻게 줄일까?\"까지 이야기하면 자료를 생활에 활용하는 단계로 이어집니다.", "이렇게 물어보세요: \"이 그래프를 아파트 게시판에 붙인다면 제목을 뭐라고 할까?\""]}]}, {"type": "more", "items": [{"title": "그림그래프로 바꾸기", "body": "병 그림 하나를 5개로 정하고 다시 그려요."}, {"title": "두 주 비교하기", "body": "지난주와 이번 주 그래프를 나란히 붙여 비교해요."}, {"title": "다른 주제 조사", "body": "가족이 좋아하는 반찬, 하루 물 마신 컵 수도 조사해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "조사표와 막대그래프 기록지 (A4 1장)"}, {"label": "키트", "value": "필요 없어요"}, {"label": "교육과정 연결", "value": "3~4학년 자료의 정리 (그림그래프, 막대그래프)"}]}]$json$::jsonb,13);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('cube-nets','수학','5~6','직육면체','정육면체 전개도 찾기','우유팩 판으로 전개도를 오려 접어 보며, 정육면체가 되는 11가지 모양을 찾아요.','난이도 ★★☆ 보통','40분','{}'::text[],array['우유팩']::text[],'assets/img/m4.jpg',false,'assets/pdf/cube-nets.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "전개도 찾기 도안", "how": "문제 14개와 정답 (A4 2장)", "kit": false}, {"name": "우유팩", "how": "펼쳐서 튼튼한 전개도를 만들 때 써요", "kit": false}, {"name": "자, 연필, 가위, 테이프", "how": "칸 크기를 똑같이 그리는 것이 중요해요", "kit": false}, {"name": "색연필", "how": "마주 보는 면을 같은 색으로 칠해요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "먼저 예상하기", "body": "도안의 그림 14개를 보고, 접지 않고 머릿속으로만 생각해서 O와 X를 표시해요.", "warn": "", "image": null}, {"title": "헷갈리면 오려서 접기", "body": "자신 없는 그림은 도안을 오려 실제로 접어 확인해요. 면이 겹치거나 빈 곳이 생기면 X예요.", "warn": "", "image": null}, {"title": "우유팩으로 크게 만들기", "body": "마음에 드는 전개도 하나를 펼친 우유팩에 한 칸 5cm로 옮겨 그려요. 자로 재서 칸 크기를 똑같이 맞춘 뒤 오려 접고 테이프로 붙여요.", "warn": "", "image": null}, {"title": "정답 맞혀 보기", "body": "도안 2쪽의 정답과 비교해요. 정육면체 전개도는 모두 11가지인데, 몇 개를 찾았나요?", "warn": "", "image": null}, {"title": "마주 보는 면 칠하기", "body": "접었을 때 서로 마주 보게 되는 면을 같은 색으로 칠해요. 전개도에서 어떤 규칙이 보이나요?", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "전개도 찾기 도안", "desc": "진짜 전개도 11개와 함정 3개를 섞어 놓은 문제지, 그리고 정답과 안 되는 까닭을 담은 해설지. A4 2장.", "pdf": "assets/pdf/cube-nets.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["한 줄에 5칸이 이어진 전개도는 왜 정육면체가 될 수 없을까요?", "정육면체의 꼭짓점 하나에는 면이 몇 개 모이나요?", "전개도에서 바로 붙어 있는 두 면이 접은 뒤 마주 보는 면이 될 수 있을까요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["정육면체는 똑같은 정사각형 6개로 이루어진 상자예요. 상자의 모서리를 잘라 납작하게 펼친 그림을 전개도라고 해요. 어디를 자르느냐에 따라 모양이 달라지는데, 정육면체 전개도는 모두 11가지가 있어요."]}, {"label": "부모님께", "paras": ["5학년 '직육면체' 단원에서는 전개도를 그리고, 접었을 때 겹치는 면이나 마주 보는 면을 찾습니다. 머릿속으로 접어 보는 공간 감각은 그림만 봐서는 잘 늘지 않으니, 헷갈릴 때마다 직접 오려 접게 해 주세요. 한 줄에 놓인 세 면 가운데 양 끝 두 면이 마주 보게 된다는 규칙을 아이 스스로 찾으면 큰 도움이 됩니다.", "이렇게 물어보세요: \"주사위에서 1의 반대편에는 왜 항상 6이 있을까?\""]}]}, {"type": "more", "items": [{"title": "우유팩 주사위", "body": "마주 보는 두 면의 눈의 합이 7이 되게 숫자를 그려요."}, {"title": "휴지 상자 펼치기", "body": "직육면체 상자를 펼쳐 보고 전개도를 따라 그려요."}, {"title": "가족 퀴즈", "body": "아이가 문제를 내고 부모님이 맞혀 보세요."}]}, {"type": "info", "items": [{"label": "도안", "value": "전개도 문제 14개와 정답 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 직육면체 (정육면체의 전개도)"}]}]$json$::jsonb,14);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('sugar-cube-volume','수학','5~6','직육면체의 부피','각설탕 부피 재기','각설탕을 쌓아 상자 크기를 비교하고, 왜 cm³라는 약속 단위가 필요한지 알아봐요.','난이도 ★★☆ 보통','40분','{}'::text[],array['상자']::text[],'assets/img/m5.jpg',false,'assets/pdf/volume-record.pdf',$json$[{"type": "materials", "note": "각설탕 한 봉지면 충분해요", "rows": [{"name": "작은 상자 2~3개", "how": "치약 상자, 과자 상자, 약 상자처럼 뚜껑이 열리는 것", "kit": false}, {"name": "각설탕 1봉지", "how": "마트 커피 코너. 실험 후 다시 봉지에 담아 써요.", "kit": true}, {"name": "자", "how": "30cm 자", "kit": false}, {"name": "부피 기록지 도안", "how": "아래에서 내려받아 인쇄해요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "각설탕 한 개 재기", "body": "각설탕 한 변의 길이를 자로 재서 기록지에 적어요. 회사마다 크기가 조금씩 달라서 꼭 직접 재야 해요.", "warn": "", "image": null}, {"title": "예상하기", "body": "상자들을 눈으로만 보고 어느 상자가 가장 큰지, 각설탕이 몇 개 들어갈지 예상해서 적어요.", "warn": "", "image": null}, {"title": "한 층 깔고 쌓기", "body": "상자 바닥에 각설탕을 빈틈없이 한 층 깔고 개수를 세요. 그다음 몇 층까지 쌓이는지 확인해 '한 층 개수 × 층 수'로 계산해요.", "warn": "", "image": null}, {"title": "자로 재서 계산하기", "body": "상자 안쪽의 가로, 세로, 높이를 cm로 재고 곱해서 부피(cm³)를 구해요.", "warn": "", "image": null}, {"title": "두 결과 비교하기", "body": "각설탕 개수와 계산한 cm³가 왜 다른지 이야기해요. 기록지의 질문에 답을 적어요.", "warn": "", "image": null}], "notes": []}, {"type": "template", "title": "부피 기록지", "desc": "상자별 측정표, 두 방법을 비교하는 질문, 1cm 모눈이 한 장에 들어 있어요. A4 1장.", "pdf": "assets/pdf/volume-record.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["각설탕을 하나하나 다 세지 않고 빨리 세는 방법은 무엇인가요?", "모양은 다른데 부피는 같은 상자가 있을까요?", "각설탕 한 개는 몇 cm³쯤 될까요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["부피는 물건이 차지하는 공간의 크기예요. 각설탕으로 재면 각설탕 크기에 따라 개수가 달라져서 사람마다 답이 달라요. 그래서 모두가 똑같이 쓰려고 '한 변이 1cm인 정육면체'를 약속 단위로 정했어요. 이것이 1cm³(1세제곱센티미터)예요."]}, {"label": "부모님께", "paras": ["6학년 '직육면체의 부피와 겉넓이' 단원은 임의 단위로 부피를 비교한 뒤 표준 단위 1cm³의 필요성을 배우고, (가로)×(세로)×(높이) 공식을 '한 층의 개수 × 층 수'로 이해하는 흐름입니다. 각설탕은 한 변이 1cm보다 커서 개수와 계산값이 달라지는데, 이 차이가 표준 단위가 왜 필요한지 이야기할 좋은 기회입니다. 상자 두께 때문에 안쪽이 바깥보다 조금 작다는 점도 함께 짚어 주세요.", "이렇게 물어보세요: \"택배 회사는 상자 크기를 어떻게 정할까?\""]}]}, {"type": "more", "items": [{"title": "1L 우유팩 재기", "body": "1L 우유팩의 가로, 세로, 높이를 재서 계산하면 1000cm³와 얼마나 가까울까요?"}, {"title": "같은 부피 다른 모양", "body": "각설탕 12개로 모양이 다른 직육면체를 여러 개 쌓아 봐요."}, {"title": "겉넓이 구하기", "body": "상자를 펼쳐 여섯 면의 넓이를 모두 더해 봐요."}]}, {"type": "info", "items": [{"label": "도안", "value": "부피 기록지 (A4 1장)"}, {"label": "키트", "value": "1cm 정육면체 블록 세트 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 직육면체의 부피 (1cm³, 부피 구하는 방법)"}]}]$json$::jsonb,15);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('alphabet-blocks','영어','3~4','알파벳과 낱말','우유팩 알파벳 블록','우유팩으로 만든 블록에 알파벳 카드를 붙여, 쌓고 굴리며 A부터 Z까지 익혀요.','난이도 ★☆☆ 쉬움','만들기 40분 · 놀이 10분','{}'::text[],array['우유팩']::text[],'assets/img/en1.jpg',true,'assets/pdf/alphabet-cards.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 우유팩을 모아 두세요", "rows": [{"name": "1L 우유팩 4~5개", "how": "깨끗이 씻어 말려요. 2개를 엇갈려 끼우면 정육면체 블록 1개가 돼요.", "kit": false}, {"name": "알파벳 카드 도안", "how": "A~Z 26장 (A4 2장)", "kit": false}, {"name": "풀, 가위, 테이프", "how": "투명 테이프로 덮으면 오래 써요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "블록 만들기", "body": "우유팩 아랫부분을 높이 7cm 정도로 잘라 상자 2개를 만들고, 서로 입구를 맞대어 끼우면 정육면체 블록이 돼요.", "warn": "", "image": null}, {"title": "카드 붙이기", "body": "알파벳 카드를 오려 블록 면에 하나씩 붙여요. 블록 5개면 26글자를 모두 붙일 수 있어요.", "warn": "", "image": null}, {"title": "굴려서 말하기", "body": "블록을 굴려 위에 나온 글자를 읽고, 그 글자로 시작하는 낱말을 말해요. \"B! B is for ball!\"", "warn": "", "image": null}, {"title": "이름 쌓기", "body": "블록을 돌려 가며 내 영어 이름이나 cat, dog 같은 짧은 낱말을 만들어 쌓아요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻과 쓰는 때"], "rows": [["What letter is it?", "무슨 글자야? (블록을 굴린 뒤 물어요)"], ["It's B.", "B야."], ["B is for ball.", "B는 ball(공)의 B야. (글자와 낱말을 이어 말해요)"], ["Big B, little b.", "대문자 B, 소문자 b."]], "note": ""}, {"type": "template", "title": "알파벳 카드 도안", "desc": "대문자와 소문자, 그 글자로 시작하는 쉬운 낱말이 함께 있는 카드 26장. A4 2장.", "pdf": "assets/pdf/alphabet-cards.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["3~4학년 영어는 알파벳을 보고 이름을 말하며, 대문자와 소문자를 짝짓는 데서 시작합니다. 글자 이름(비, 씨)과 낱말 속 소리(ㅂ, ㅋ)가 다르다는 것을 놀이 속에서 자연스럽게 느끼게 해 주세요. 발음이 걱정되면 사전 앱의 듣기 버튼을 아이와 함께 눌러 보세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Good job! · Great! · You did it!", "잘했어! · 멋져! · 해냈구나! 틀려도 \"Nice try!(좋은 시도야!)\"라고 말해 주세요."]}]}, {"type": "more", "items": [{"title": "알파벳 순서 기차", "body": "카드를 A부터 Z까지 줄 세우며 노래를 불러요."}, {"title": "집 안 보물찾기", "body": "B 카드를 들고 b로 시작하는 물건(book, bag)을 찾아요."}, {"title": "짝 맞추기", "body": "대문자와 소문자를 따로 오려 뒤집어 놓고 짝을 찾아요."}]}, {"type": "info", "items": [{"label": "도안", "value": "알파벳 카드 26장 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 알파벳 대소문자, 쉬운 낱말 읽기"}]}]$json$::jsonb,16);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('fruit-shop','영어','3~4','물건 사고팔기','박스 과일 가게','택배 상자로 과일 가게를 차리고, 영어로 사고파는 역할놀이를 해요.','난이도 ★☆☆ 쉬움','30분','{}'::text[],array['상자']::text[],'assets/img/en2.jpg',true,'assets/pdf/fruit-shop.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "택배 상자 1개", "how": "옆으로 눕혀 가게 진열대로 써요", "kit": false}, {"name": "과일 카드 도안", "how": "과일 12종과 가게 대본 (A4 1장)", "kit": false}, {"name": "장난감 돈", "how": "진짜 동전이나 이면지로 만든 종이돈", "kit": false}, {"name": "진짜 과일 몇 개", "how": "있으면 더 실감 나요 (없어도 돼요)", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "가게 차리기", "body": "상자를 옆으로 눕혀 진열대를 만들고, 과일 카드를 오려 세워 놓아요.", "warn": "", "image": null}, {"title": "가격 정하기", "body": "아이와 함께 과일마다 가격을 정해 카드 아래에 적어요. 100원 단위로 정하면 계산하기 쉬워요.", "warn": "", "image": null}, {"title": "대본대로 사고팔기", "body": "처음에는 부모님이 손님, 아이가 주인을 해요. 대본을 보며 천천히 말해요.", "warn": "", "image": null}, {"title": "역할 바꾸기", "body": "익숙해지면 역할을 바꾸고, 대본 없이 해 봐요. 과일 두 개를 사며 \"Two apples, please.\"에도 도전해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "가게 대본", "head": ["누가", "영어", "뜻"], "rows": [["손님", "Hello! Can I have an apple, please?", "안녕하세요! 사과 하나 주세요."], ["주인", "Sure. Here you are.", "네. 여기 있어요."], ["손님", "How much is it?", "얼마예요?"], ["주인", "It's 500 won.", "500원이에요."], ["손님", "Thank you!", "고맙습니다!"]], "note": "apple, orange처럼 모음 소리로 시작하는 낱말 앞에는 a 대신 an을 써요. (an apple, a banana)"}, {"type": "template", "title": "과일 카드와 가격표", "desc": "apple부터 kiwi까지 과일 카드 12장, 가격 쓰는 칸, 가게 대본이 한 장에 있어요. A4 1장.", "pdf": "assets/pdf/fruit-shop.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["3~4학년 영어는 실제 상황에서 쓰는 짧은 표현을 듣고 말하는 데 집중합니다. 가게 놀이는 같은 표현을 여러 번 자연스럽게 반복하게 해 줘서 효과가 좋아요. 아이가 문장을 다 말하지 못해도 \"Apple, please!\"처럼 낱말만 말해도 충분히 칭찬해 주세요."]}, {"label": "수학도 함께", "paras": ["\"사과 2개와 바나나 1개는 모두 얼마일까?\" 가격을 더하고 거스름돈을 계산하면 덧셈·뺄셈 연습도 돼요."]}]}, {"type": "more", "items": [{"title": "문구점 가게", "body": "과일 대신 pencil, eraser, ruler로 가게를 바꿔요."}, {"title": "마트에서 실전", "body": "장 보러 가서 과일 이름을 영어로 말해 봐요."}, {"title": "좋아하는 과일 묻기", "body": "\"Do you like bananas?\" \"Yes, I do. / No, I don't.\""}]}, {"type": "info", "items": [{"label": "도안", "value": "과일 카드 12장과 가게 대본 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 물건 사기, 가격 묻고 답하기"}]}]$json$::jsonb,17);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('family-puppets','영어','3~4','가족 소개하기','휴지심 가족 인형','휴지심으로 우리 가족 인형을 만들고, 인형극으로 가족을 영어로 소개해요.','난이도 ★☆☆ 쉬움','40분','{}'::text[],array['휴지심']::text[],'assets/img/en3.jpg',true,'assets/pdf/family-puppets.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 휴지심을 모아 두세요", "rows": [{"name": "휴지심 (가족 수만큼)", "how": "다 쓴 두루마리 휴지 심", "kit": false}, {"name": "가족 인형 도안", "how": "얼굴 동그라미, 가족 낱말 카드, 소개 문장 (A4 1장)", "kit": false}, {"name": "색연필, 털실, 자투리 천", "how": "머리카락과 옷을 꾸며요", "kit": false}, {"name": "풀, 가위", "how": "얼굴과 이름표를 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "얼굴 그리기", "body": "도안의 동그라미에 가족 얼굴을 그리고 오려요. 아빠의 안경, 동생의 머리핀처럼 특징을 살려요.", "warn": "", "image": null}, {"title": "휴지심에 붙이기", "body": "얼굴을 휴지심 위쪽에 붙이고, 휴지심 몸통에 천이나 색종이로 옷을 입혀요.", "warn": "", "image": null}, {"title": "이름표 달기", "body": "가족 낱말 카드를 오려 인형 앞에 붙여요. father, mother처럼 영어 낱말을 소리 내어 읽으며 붙여요.", "warn": "", "image": null}, {"title": "가족 인형극", "body": "인형을 하나씩 들어 보이며 \"This is my father.\" 하고 소개해요. 가족이 실제로 앞에 있으면 더 신나요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["Who is he? / Who is she?", "이 사람은 누구야? (남자 / 여자)"], ["This is my mother.", "우리 엄마예요."], ["She is kind. / He is tall.", "엄마는 친절해요. / 키가 커요."], ["I love my family!", "나는 우리 가족을 사랑해요!"]], "note": "남자 가족은 he, 여자 가족은 she로 바꿔 말해요. 꾸미는 말: funny(재미있는), smart(똑똑한), strong(힘센), pretty(예쁜)"}, {"type": "template", "title": "가족 인형 도안", "desc": "얼굴 그리는 동그라미 8개, 가족 낱말 카드 8장(grandfather부터 me까지), 소개 문장. A4 1장.", "pdf": "assets/pdf/family-puppets.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["사람을 소개하는 표현은 3~4학년 영어의 기본 표현입니다. 인형을 쓰면 아이가 직접 말하는 부담이 줄어들어, 수줍음 많은 아이도 쉽게 따라 해요. 영어에는 형, 오빠, 남동생이 모두 brother 한 낱말이라는 것도 재미있게 알려 주세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Wonderful! · I like your puppet!", "멋지다! · 네 인형 마음에 들어!"]}]}, {"type": "more", "items": [{"title": "누구일까요 퀴즈", "body": "이름표를 가리고 \"Who is she?\" 하고 맞혀요."}, {"title": "반려동물 인형", "body": "\"This is my dog. His name is Choco.\""}, {"title": "영상 편지", "body": "인형극을 휴대폰으로 찍어 할머니께 보내요."}]}, {"type": "info", "items": [{"label": "도안", "value": "얼굴, 가족 카드, 소개 문장 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 사람 소개하기, 가족 낱말"}]}]$json$::jsonb,18);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('weather-wheel','영어','3~4','날씨 묻고 답하기','이면지 날씨 돌림판','현관에 날씨 돌림판을 걸고, 매일 아침 창밖을 보며 오늘 날씨를 영어로 말해요.','난이도 ★☆☆ 쉬움','만들기 30분 · 매일 1분','{}'::text[],array['이면지']::text[],'assets/img/en4.jpg',true,'assets/pdf/weather-wheel.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "날씨 돌림판 도안", "how": "이면지에 인쇄해도 돼요 (A4 1장)", "kit": false}, {"name": "두꺼운 종이", "how": "과자 상자나 택배 상자를 펼쳐서", "kit": false}, {"name": "할핀 1개", "how": "화살표를 돌릴 수 있게 고정해요 (없으면 압정과 지우개)", "kit": false}, {"name": "풀, 가위, 끈", "how": "벽이나 현관문에 걸 때 써요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "판 만들기", "body": "도안을 두꺼운 종이에 붙이고 큰 원과 화살표를 오려요.", "warn": "", "image": null}, {"title": "화살표 달기", "body": "원 가운데 점과 화살표 아래쪽 점을 맞추고 할핀으로 꽂아요. 화살표가 빙글빙글 도는지 확인해요.", "warn": "", "image": null}, {"title": "현관에 걸기", "body": "아이 눈높이에 맞춰 현관문이나 창문 옆에 걸어요.", "warn": "", "image": null}, {"title": "매일 아침 1분", "body": "학교 가기 전에 부모님이 \"How's the weather today?\" 하고 물으면, 아이가 창밖을 보고 화살표를 돌리며 대답해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["How's the weather today?", "오늘 날씨 어때?"], ["It's sunny. / It's rainy.", "맑아. / 비가 와."], ["Take your umbrella!", "우산 챙겨! (rainy일 때)"], ["Let's go outside!", "밖에 나가자! (sunny일 때)"]], "note": "돌림판 낱말: sunny(맑은), cloudy(흐린), rainy(비 오는), snowy(눈 오는), windy(바람 부는), hot(더운)"}, {"type": "template", "title": "날씨 돌림판 도안", "desc": "날씨 그림 6칸 원판, 화살표, 아침 대화 문장. A4 1장.", "pdf": "assets/pdf/weather-wheel.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["외국어는 짧게라도 매일 쓰는 것이 가장 효과적입니다. 하루 1분 날씨 대화를 아침 습관으로 만들어 보세요. 한 달이면 날씨 낱말 6개와 질문·대답 표현이 자연스럽게 입에 붙어요."]}, {"label": "과학도 함께", "paras": ["한 달 동안 날씨를 달력에 기록하면, 수학 '재활용품 막대그래프'처럼 날씨 그래프도 그릴 수 있어요."]}]}, {"type": "more", "items": [{"title": "옷 입히기 놀이", "body": "\"It's cold. Wear your coat!\" 날씨에 맞는 옷을 말해요."}, {"title": "일기 예보관", "body": "TV 기상캐스터처럼 내일 날씨를 영어로 발표해요."}, {"title": "세계 날씨", "body": "지금 다른 나라 날씨를 찾아보고 비교해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "날씨 돌림판과 화살표 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 날씨 묻고 답하기"}]}]$json$::jsonb,19);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('color-bowling','영어','3~4','색깔과 수','종이컵 색깔 볼링','색깔 카드를 붙인 종이컵을 신문지 공으로 쓰러뜨리고, 쓰러진 컵의 색과 개수를 영어로 외쳐요.','난이도 ★☆☆ 쉬움','30분','{}'::text[],array['종이컵']::text[],'assets/img/en5.jpg',true,'assets/pdf/color-bowling.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 종이컵과 신문지면 끝", "rows": [{"name": "종이컵 10개", "how": "다 쓴 종이컵이나 요구르트병", "kit": false}, {"name": "신문지 공", "how": "신문지나 이면지를 뭉쳐 테이프로 감아요", "kit": false}, {"name": "색깔 카드 도안", "how": "색깔 10장과 점수판 (A4 1장)", "kit": false}, {"name": "테이프, 가위", "how": "카드를 컵에 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "핀 만들기", "body": "색깔 카드를 오려 종이컵에 하나씩 붙이고, 컵을 엎어서 1-2-3-4 삼각형으로 세워요.", "warn": "", "image": null}, {"title": "공 굴리기", "body": "2~3m 떨어진 곳에서 신문지 공을 굴려요.", "warn": "", "image": null}, {"title": "색깔 외치기", "body": "쓰러진 컵을 하나씩 들며 색깔을 외쳐요. \"Red! Blue! Green!\"", "warn": "", "image": null}, {"title": "개수 세고 기록하기", "body": "\"How many cups?\" 하고 물으면 영어로 세어 대답해요. 점수판에 색깔과 개수를 적고, 다섯 판을 모아 이긴 사람을 정해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["What color is it?", "무슨 색이야?"], ["It's red.", "빨간색이야."], ["How many cups?", "컵이 몇 개야?"], ["Five cups! / Strike!", "다섯 개! / 스트라이크(모두 쓰러뜨림)!"]], "note": "수 낱말: one, two, three, four, five, six, seven, eight, nine, ten. 컵이 2개 이상이면 cups처럼 끝에 s를 붙여요."}, {"type": "template", "title": "색깔 카드와 점수판", "desc": "red부터 brown까지 색깔 카드 10장, 6판까지 기록하는 점수판, 외치는 문장. A4 1장.", "pdf": "assets/pdf/color-bowling.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["몸을 움직이며 말하면 낱말이 훨씬 오래 기억에 남아요. 볼링처럼 신나는 놀이에서는 아이가 영어를 '공부'가 아니라 '게임 규칙'으로 받아들여 부담 없이 말하게 됩니다. 점수를 매길 때 영어 숫자를 꼭 함께 말해 주세요."]}, {"label": "이렇게 응원해 주세요", "paras": ["Go! Go! · Almost! · Awesome!", "힘내! · 아깝다! · 최고야!"]}]}, {"type": "more", "items": [{"title": "색깔 찾기 술래", "body": "\"Find something yellow!\" 하면 집 안에서 노란 물건을 찾아와요."}, {"title": "색 섞기 실험", "body": "\"Red and yellow make orange!\" 물감으로 확인해요."}, {"title": "점수 덧셈", "body": "색마다 점수를 다르게 정해 합계를 영어로 말해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "색깔 카드 10장과 점수판 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 색깔 낱말, 1~10 수 세기"}]}]$json$::jsonb,20);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('town-map','영어','5~6','길 묻고 안내하기','상자 동네 지도','택배 상자 위에 우리 동네를 펼치고, 작은 인형을 영어로 길 안내해 목적지까지 데려가요.','난이도 ★★☆ 보통','30분','{}'::text[],array['상자']::text[],'assets/img/en6.jpg',true,'assets/pdf/town-map.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "택배 상자 뚜껑", "how": "지도판으로 써요", "kit": false}, {"name": "동네 지도 도안", "how": "지도와 표현 카드 6장 (A4 1장)", "kit": false}, {"name": "작은 인형이나 지우개", "how": "지도 위를 걸어 다닐 말이에요", "kit": false}, {"name": "작은 상자들 (선택)", "how": "약 상자로 건물을 세우면 입체 지도가 돼요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "지도 붙이기", "body": "지도를 상자 뚜껑에 붙여요. 작은 상자로 건물을 세우면 더 실감 나요.", "warn": "", "image": null}, {"title": "출발점에 서기", "body": "인형을 START에 세우고, 한 사람이 \"Where is the library?\" 하고 물어요.", "warn": "", "image": null}, {"title": "말로만 안내하기", "body": "다른 사람은 표현 카드를 보며 \"Go straight. Turn left.\" 하고 말로만 안내해요. 묻는 사람은 들은 대로만 인형을 움직여요.", "warn": "", "image": null}, {"title": "도착 확인하기", "body": "\"It's next to the bank.\"처럼 위치를 설명하고, 맞게 도착했는지 확인한 뒤 역할을 바꿔요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["Where is the library?", "도서관이 어디예요?"], ["Go straight.", "쭉 가세요."], ["Turn left. / Turn right.", "왼쪽으로 / 오른쪽으로 도세요."], ["It's next to the bank.", "은행 옆에 있어요."], ["It's across from the park.", "공원 맞은편에 있어요."]], "note": "left와 right는 인형이 바라보는 방향을 기준으로 해요. 아이와 인형의 방향이 다를 때 헷갈리니, 처음에는 인형 뒤에서 같은 방향을 보며 연습해요."}, {"type": "template", "title": "동네 지도 도안", "desc": "school, hospital, library 등 건물 12개가 있는 지도와 길 안내 표현 카드 6장. A4 1장.", "pdf": "assets/pdf/town-map.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["5~6학년 영어에서는 위치를 묻고 길을 안내하는 표현을 배웁니다. 말로만 안내하는 규칙이 핵심이에요. 손가락으로 가리키지 않고 영어로만 설명해야 하니, 자연스럽게 문장을 끝까지 말하게 됩니다."]}, {"label": "우리 동네 버전", "paras": ["도안 지도가 익숙해지면, 이면지에 진짜 우리 동네 지도를 그려 학교 가는 길을 영어로 설명해 보세요."]}]}, {"type": "more", "items": [{"title": "보물찾기", "body": "한 건물 아래 보물 쪽지를 숨기고 영어로만 안내해 찾게 해요."}, {"title": "몇 블록?", "body": "\"Go straight two blocks.\"처럼 거리를 넣어 말해요."}, {"title": "집 안 길 찾기", "body": "눈을 가린 가족을 영어로 냉장고까지 안내해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "동네 지도와 표현 카드 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 위치 묻고 길 안내하기"}]}]$json$::jsonb,21);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('daily-clock','영어','5~6','하루 일과와 시각','종이접시 하루 시계','종이접시로 시계를 만들고, 일과 카드를 뽑아 바늘을 돌리며 몇 시에 무엇을 하는지 영어로 말해요.','난이도 ★★☆ 보통','30분','{}'::text[],'{}'::text[],'assets/img/en7.jpg',true,'assets/pdf/daily-clock.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "종이접시 1개", "how": "없으면 상자 판을 동그랗게 오려요", "kit": false}, {"name": "시계 도안", "how": "시계판, 바늘 2개, 일과 카드 8장 (A4 1장)", "kit": false}, {"name": "할핀 1개", "how": "바늘이 돌아가게 고정해요", "kit": false}, {"name": "풀, 가위", "how": "바늘은 상자 판에 붙여 오리면 튼튼해요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "시계 만들기", "body": "시계판을 오려 종이접시에 붙이고, 긴바늘과 짧은바늘을 가운데에 할핀으로 고정해요.", "warn": "", "image": null}, {"title": "일과 카드 채우기", "body": "카드 8장의 빈칸에 실제 내 시각을 적어요. 예: I get up at seven .", "warn": "", "image": null}, {"title": "묻고 바늘 돌리기", "body": "부모님이 카드 한 장을 뽑아 \"What time do you get up?\" 하고 물으면, 아이가 바늘을 돌려 시각을 맞추고 대답해요.", "warn": "", "image": null}, {"title": "순서대로 하루 말하기", "body": "카드 8장을 시간 순서로 늘어놓고, 아침부터 밤까지 내 하루를 영어로 이어서 말해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["What time do you get up?", "몇 시에 일어나니?"], ["I get up at seven.", "7시에 일어나요."], ["I go to school at eight thirty.", "8시 30분에 학교에 가요."], ["What time is it? / It's nine o'clock.", "몇 시야? / 9시 정각이야."]], "note": "시각 읽기: 7:00 seven (o'clock), 7:30 seven thirty, 7:15 seven fifteen. 시와 분을 숫자 그대로 이어 읽으면 돼요."}, {"type": "template", "title": "하루 시계 도안", "desc": "1~12 숫자와 분 눈금이 있는 시계판, 긴바늘·짧은바늘, 빈칸 일과 카드 8장. A4 1장.", "pdf": "assets/pdf/daily-clock.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["5~6학년 영어는 자신의 생활을 문장으로 말하고 쓰는 단계로 넘어갑니다. 실제 아이의 하루로 문장을 만들면 외운 문장이 아니라 '내 이야기'가 되어 훨씬 잘 기억해요. 아날로그 시계 읽기 복습도 함께 됩니다."]}, {"label": "가족 버전", "paras": ["아이가 부모님께 물어보게 해 보세요. \"What time do you go to work?\" 주어가 바뀌는 연습이 돼요."]}]}, {"type": "more", "items": [{"title": "주말 일과", "body": "\"On Saturday, I get up at nine.\" 평일과 비교해요."}, {"title": "시각 맞히기 게임", "body": "한 사람이 바늘을 돌리면 다른 사람이 영어로 시각을 말해요."}, {"title": "일과표 꾸미기", "body": "카드를 벽에 붙여 방학 생활 계획표로 써요."}]}, {"type": "info", "items": [{"label": "도안", "value": "시계판, 바늘, 일과 카드 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 하루 일과, 시각 묻고 답하기"}]}]$json$::jsonb,22);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('sentence-dice','영어','5~6','문장 만들기','우유팩 문장 주사위','''누가'', ''무엇을'', ''언제'' 주사위 세 개를 함께 굴려, 나온 대로 영어 문장을 만들어요.','난이도 ★★☆ 보통','만들기 30분 · 놀이 15분','{}'::text[],array['우유팩']::text[],'assets/img/en8.jpg',true,'assets/pdf/sentence-dice.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "문장 주사위 도안", "how": "주사위 전개도 3개와 문장 기록지 (A4 2장)", "kit": false}, {"name": "우유팩 2개", "how": "펼쳐서 전개도를 붙이면 튼튼한 주사위가 돼요", "kit": false}, {"name": "풀, 가위, 테이프", "how": "접어서 모서리를 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "주사위 세 개 만들기", "body": "전개도를 우유팩 판에 붙여 오리고, 접어서 테이프로 붙여요. 수학 '정육면체 전개도' 활동과 이어서 해도 좋아요.", "warn": "", "image": null}, {"title": "한꺼번에 굴리기", "body": "세 주사위를 함께 굴리고, 누가 → 무엇을 → 언제 순서로 줄 세워요.", "warn": "", "image": null}, {"title": "문장 읽기", "body": "나온 대로 소리 내어 읽어요. \"They / eat pizza / on Sunday.\" 웃기는 문장이 나와도 괜찮아요!", "warn": "", "image": null}, {"title": "He, She 규칙 지키기", "body": "He나 She가 나오면 동사 끝에 s를 붙여야 해요. \"He plays soccer.\" 규칙을 지키면 1점 더!", "warn": "", "image": null}, {"title": "기록지에 쓰기", "body": "가장 마음에 드는 문장 8개를 기록지에 옮겨 써요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "주사위에 들어 있는 말", "head": ["주사위", "여섯 면"], "rows": [["① 누가", "I(나), You(너), We(우리), They(그들), He(그), She(그녀)"], ["② 무엇을", "play soccer(축구하다), read books(책을 읽다), eat pizza(피자를 먹다), watch TV(TV를 보다), ride a bike(자전거를 타다), sing a song(노래하다)"], ["③ 언제", "every day(매일), on Sunday(일요일에), after school(방과 후에), at night(밤에), in the morning(아침에), on weekends(주말마다)"]], "note": "He, She일 때 바뀌는 모양: plays, reads, eats, watches, rides, sings. watch처럼 ch로 끝나면 es를 붙여요."}, {"type": "template", "title": "문장 주사위 도안", "desc": "색깔이 다른 주사위 전개도 3개와 문장 8개를 적는 기록지. A4 2장.", "pdf": "assets/pdf/sentence-dice.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["영어 문장이 '누가 + 무엇을 한다 + 언제' 순서로 만들어진다는 것을 놀이로 몸에 익히는 활동입니다. 주어에 따라 동사 모양이 바뀌는 규칙(3인칭 단수 -s)은 중학교까지 이어지는 중요한 문법이에요. 틀려도 바로 고쳐 주기보다 \"He는 어떻게 했더라?\" 하고 스스로 떠올리게 해 주세요."]}, {"label": "빈 주사위로 늘리기", "paras": ["우유팩으로 빈 주사위를 하나 더 만들어 아이가 아는 동사를 직접 써 넣게 하면, 문장 수가 계속 늘어나요."]}]}, {"type": "more", "items": [{"title": "진짜일까?", "body": "나온 문장이 우리 가족에게 맞으면 \"True!\", 아니면 \"False!\""}, {"title": "질문으로 바꾸기", "body": "\"Do you read books every day?\" 처럼 Do를 앞에 붙여 물어봐요."}, {"title": "그림 문장", "body": "가장 웃긴 문장을 골라 그림으로 그려요."}]}, {"type": "info", "items": [{"label": "도안", "value": "주사위 전개도 3개와 기록지 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 일상 문장 말하고 쓰기"}]}]$json$::jsonb,23);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('earth-poster','영어','5~6','해야 할 일 말하기','지구 지킴이 포스터','재활용 실험을 해 본 우리 아이가 지구를 지키는 방법을 영어 포스터로 만들어 현관에 붙여요.','난이도 ★★☆ 보통','40분','{}'::text[],array['이면지']::text[],'assets/img/en9.jpg',true,'assets/pdf/earth-poster.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "포스터 도안", "how": "포스터 틀과 단어 상자 (A4 2장)", "kit": false}, {"name": "색연필, 사인펜", "how": "그림과 글씨를 꾸며요", "kit": false}, {"name": "재활용 꾸미기 재료", "how": "병뚜껑, 과자 봉지 조각, 잡지 사진을 오려 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "이야기 나누기", "body": "우리 집에서 지구를 위해 하는 일, 하면 안 되는 일을 한국어로 먼저 이야기해요. 수학 '재활용품 막대그래프' 결과를 함께 보면 좋아요.", "warn": "", "image": null}, {"title": "단어 고르기", "body": "도안 2쪽 단어 상자에서 해야 할 일 3개, 하면 안 되는 일 2개를 골라요.", "warn": "", "image": null}, {"title": "문장 완성하기", "body": "포스터의 We should, We shouldn't 뒤에 고른 표현을 옮겨 써요. 소리 내어 읽으며 써요.", "warn": "", "image": null}, {"title": "그리고 꾸미기", "body": "빈 칸에 지구 그림을 그리고, 재활용 재료를 붙여 꾸며요.", "warn": "", "image": null}, {"title": "가족 앞에서 발표", "body": "현관에 붙이고 가족 앞에서 영어로 읽어요. 일주일 동안 포스터대로 실천했는지 확인해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["We should save water.", "우리는 물을 아껴야 해요."], ["We should recycle paper.", "우리는 종이를 재활용해야 해요."], ["We shouldn't waste food.", "우리는 음식을 남기면 안 돼요."], ["Let's save the Earth together!", "함께 지구를 지켜요!"]], "note": "shouldn't는 should not을 줄인 말이에요."}, {"type": "template", "title": "포스터 도안", "desc": "SAVE THE EARTH! 포스터 틀과, 뜻이 함께 적힌 표현 10개가 들어 있는 단어 상자. A4 2장.", "pdf": "assets/pdf/earth-poster.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["5~6학년에서는 의무나 충고를 나타내는 should를 배웁니다. DNA 키즈랩의 재활용 활동과 이어지는 주제라, 아이가 직접 겪은 일을 영어로 표현하게 돼요. 포스터처럼 '누군가에게 보여 줄 결과물'이 있으면 쓰기 동기가 크게 올라갑니다."]}, {"label": "자랑하기", "paras": ["완성한 포스터 사진을 찍어 두세요. 나중에 '우리집 실험 자랑' 게시판에 올릴 수 있어요."]}]}, {"type": "more", "items": [{"title": "교실 규칙 포스터", "body": "\"We should be quiet in the library.\" 같은 규칙을 만들어요."}, {"title": "실천 체크표", "body": "포스터 문장 옆에 일주일 동안 지킨 날을 표시해요."}, {"title": "충고 놀이", "body": "\"I'm tired.\" \"You should go to bed early.\""}]}, {"type": "info", "items": [{"label": "도안", "value": "포스터 틀과 단어 상자 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 해야 할 일 말하고 쓰기 (should)"}]}]$json$::jsonb,24);
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('summer-minibook','영어','5~6','지난 일 말하기','여름방학 미니북','이면지 한 장을 접어 8쪽짜리 작은 책을 만들고, 방학 동안 한 일을 영어 그림책으로 남겨요.','난이도 ★★★ 도전','50분','{}'::text[],array['이면지']::text[],'assets/img/en10.jpg',true,'assets/pdf/summer-minibook.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 이면지 한 장이면 책 한 권", "rows": [{"name": "미니북 도안", "how": "8쪽 틀과 접는 법·과거형 단어 (A4 2장). 1쪽만 인쇄해 접어요.", "kit": false}, {"name": "가위", "how": "가운데 빨간 선 하나만 잘라요", "kit": false}, {"name": "색연필, 방학 사진", "how": "그림을 그리거나 작게 인쇄한 사진을 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "미니북 접기", "body": "도안 1쪽을 인쇄해 2쪽의 접는 법대로 8칸 자국을 내고, 가운데 빨간 선만 잘라 책 모양으로 접어요. 윗줄이 거꾸로 인쇄된 것은 접으면 바르게 보이게 하려는 거예요.", "warn": "", "image": null}, {"title": "방학 떠올리기", "body": "방학 사진을 함께 보며 어디에 갔는지, 누구와 갔는지, 무엇을 보고 먹었는지 한국어로 이야기해요.", "warn": "", "image": null}, {"title": "빈칸 채우기", "body": "쪽마다 이미 적힌 문장의 빈칸을 채워요. 예: I went to the beach . 모르는 낱말은 사전 앱으로 함께 찾아요.", "warn": "", "image": null}, {"title": "그림 넣기", "body": "네모 칸에 그림을 그리거나 사진을 붙이고, 표지에 이름을 써요.", "warn": "", "image": null}, {"title": "작가 낭독회", "body": "완성한 책을 가족 앞에서 읽어 주어요. 영상으로 찍어 두면 방학 기념이 돼요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻"], "rows": [["What did you do this summer?", "이번 여름에 뭐 했어?"], ["I went to Jeju Island.", "제주도에 갔어요."], ["I saw dolphins. / I ate fish.", "돌고래를 봤어요. / 생선을 먹었어요."], ["It was great!", "정말 멋졌어요!"]], "note": "지난 일은 동사 모양이 바뀌어요. play → played처럼 ed를 붙이는 말도 있고, go → went, see → saw처럼 모양이 완전히 바뀌는 말도 있어요. 도안 2쪽에 정리되어 있어요."}, {"type": "template", "title": "여름방학 미니북 도안", "desc": "빈칸 문장이 들어간 8쪽 미니북 틀, 접는 방법 다섯 단계, 과거형 단어 8쌍과 느낌 낱말. A4 2장.", "pdf": "assets/pdf/summer-minibook.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["5~6학년 영어에서는 지난 일을 묻고 답하며, 간단한 글로 쓰는 활동을 합니다. 빈칸이 있는 문장 틀을 주면 아이가 '쓸 거리'에만 집중할 수 있어 영어 쓰기 부담이 크게 줄어요. 철자가 조금 틀려도 끝까지 완성한 것을 먼저 칭찬해 주세요."]}, {"label": "계절마다 한 권", "paras": ["겨울방학, 생일, 가족 여행마다 한 권씩 만들면 아이만의 영어 그림책 시리즈가 생겨요."]}]}, {"type": "more", "items": [{"title": "인터뷰 놀이", "body": "\"What did you do yesterday?\" 가족끼리 서로 물어봐요."}, {"title": "한 줄 영어 일기", "body": "자기 전에 오늘 한 일을 영어 한 문장으로 써요."}, {"title": "미래 미니북", "body": "\"I will ~\"로 다음 방학 계획책도 만들어요."}]}, {"type": "info", "items": [{"label": "도안", "value": "8쪽 미니북 틀과 과거형 단어 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 지난 일 묻고 답하기, 짧은 글 쓰기"}]}]$json$::jsonb,25);
